//#region ../src/lib/bots.ts
const HAND_SIZE = 7;
const TIMER_BY_DIFFICULTY = {
	easy: 6e4,
	medium: 9e4,
	hard: 135e3
};
const BASE_TIMER_MS = TIMER_BY_DIFFICULTY.medium;
const MIN_TIMER_MS = TIMER_BY_DIFFICULTY.easy;
function roundTimerMs(round, difficulty = "medium") {
	return TIMER_BY_DIFFICULTY[difficulty] ?? TIMER_BY_DIFFICULTY.medium;
}

//#endregion
//#region ../src/lib/scoring.ts
const BASE_POINTS = {
	easy: 5,
	medium: 10,
	hard: 15
};
function speedMultiplier(elapsedMs) {
	const seconds = elapsedMs / 1e3;
	if (seconds <= 15) return 2;
	if (seconds <= 30) return 1.5;
	if (seconds <= 60) return 1.25;
	return 1;
}
function basePoints(difficulty) {
	return BASE_POINTS[difficulty] ?? BASE_POINTS.medium;
}
function roundScore(difficulty, elapsedMs, correct) {
	if (!correct) return 0;
	return Math.round(basePoints(difficulty) * speedMultiplier(elapsedMs));
}

